            count_s += 1;
        } else if !distinct_chars.contains(&c) {
            distinct_chars.push(c);
        }
    }

    println!("The character 's' occurs {} times.", count_s);
    println!("There are {} distinct characters in the string.", distinct_chars.len());
}

