    let shapes = vec![
        Rectangle { width: 3, height: 4 },
        Triangle { side1: 3, side2: 4, side3: 5 },
        Rectangle { width: 2, height: 5 }
    ];

    for shape in &shapes {
        match shape {
            Rectangle { width, height } => println!("Perimeter of rectangle {}: {}", width * 2 + height * 2),
            Triangle { side1, side2, side3 } => println!("Perimeter of triangle {}: {}", side1 + side2 + side3)
        }
    }
}

